const key='kizomba-demo-v1';
const currentStationMapping={};
let db={events:[],points:[],tests:[],layoutVersion:currentLayoutVersion},selected='',selectedEquipment='',adminLayer='105',action=null,simulation=false;
const houseCodes=layoutPoints.map(p=>p.code).sort();
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID(),now=()=>new Date().toISOString(),fmt=t=>new Date(t).toLocaleString('pt-PT',{timeZone:'Africa/Luanda'}),area=code=>'Casa '+code;
function valid(d){return !!d&&Array.isArray(d.events)&&Array.isArray(d.points)&&Array.isArray(d.tests)&&d.events.every(e=>e&&typeof e.id==='string'&&typeof e.area==='string'&&typeof e.place==='string'&&typeof e.type==='string'&&['open','ack','closed'].includes(e.status)&&['manual','simulation'].includes(e.source)&&Number.isFinite(Date.parse(e.time))&&Array.isArray(e.log)&&e.log.every(l=>typeof l.text==='string'&&Number.isFinite(Date.parse(l.time))))&&d.points.every(p=>p&&typeof p.id==='string'&&typeof p.code==='string'&&typeof p.area==='string'&&typeof p.place==='string'&&typeof p.kind==='string')&&d.tests.every(t=>t&&typeof t.id==='string'&&typeof t.area==='string'&&typeof t.notes==='string'&&Number.isFinite(Date.parse(t.time))&&Array.isArray(t.checks)&&t.checks.length===checks.length&&t.checks.every(v=>typeof v==='boolean'));}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,5500);}
function save(){try{localStorage.setItem(key,JSON.stringify(db));}catch{toast('Não foi possível guardar no navegador. Exporte os registos antes de fechar.');}render();}
function render(){const opened=db.events.filter(e=>e.status!=='closed');$('openCount').textContent=opened.length;$('faultCount').textContent=opened.filter(e=>['Avaria','Sem comunicação'].includes(e.type)).length;$('pointCount').textContent=db.points.length;
renderResidence(opened);
$('stationCards').innerHTML=stations.map(st=>`<details><summary>${esc(st.id)} · ${esc(st.location)}${st.operatingName?` / ${esc(st.operatingName)}`:""} · ${st.loops.length} loops · ${esc(st.manufacturer)} ${esc(st.model)}</summary><p>Marca e modelo confirmados pelo utilizador em 08/10/2026. Composição interna por conferir individualmente; levantamentos fotográficos disponíveis para SADI 2 e SADI 4.</p>${st.ip?`<p><strong>IP documentado: ${esc(st.ip)}</strong> · Máscara: ${esc(st.subnetMask||"por confirmar")} · Gateway: por confirmar.<br>Fonte: ${esc(st.networkSource)}. ${esc(st.networkCheck)} <a href="Enderecos-Centrais-Kizomba.md" download>Relatório de rede</a></p>`:"<p>Endereço IP: por levantar no painel.</p>"}<p class="notice">Estado real: desconhecido · distribuição de 2015 com numeração antiga, sem correspondência automática com as casas actuais</p><table><tr><th>Loop</th><th>Residências · referência de 2015</th><th>Outros locais</th></tr>${st.loops.map(l=>`<tr><td>${l.n}</td><td>${esc(l.houses.map(code=>'Casa '+code).join(', ')||'Sem casas indicadas neste loop')}</td><td>${esc(l.common.join(', ')||'—')}</td></tr>`).join('')}</table></details>`).join('');
$('houses').innerHTML=houseCodes.filter(n=>{const entity=residenceEntities[n]?.entity||'Não indicada',q=$('houseSearch').value.trim().toUpperCase();return (n.includes(q)||entity.toUpperCase().includes(q))&&(!$('entityFilter').value||entity===$('entityFilter').value);}).map(n=>{const a=area(n),ev=opened.filter(e=>e.area===a),cl=ev.some(e=>!['Avaria','Sem comunicação'].includes(e.type))?'alarm':ev.length?'fault':'';return `<button class="house ${cl} ${selected===a?'selected':''}" data-house="${n}">${n}<small>${esc(residenceEntities[n]?.entity||'Não indicada')}</small><small>${ev.length?ev.length+' registo(s)':'Sem dados reais'}</small></button>`}).join('');
$('mapPoints').innerHTML=layoutPoints.map(p=>{const ev=opened.filter(e=>e.area===area(p.code));return `<button class="mapPoint ${ev.length?'hasEvent':''}" style="left:${p.x}%;top:${p.y}%" data-house="${p.code}" title="Casa ${p.code} · ${esc(residenceEntities[p.code]?.entity||'Não indicada')}: ${ev.length} ocorrência(s) registada(s)" aria-label="Casa ${p.code}, ${ev.length} registos">${p.code}</button>`}).join('');
$('areaTitle').textContent=selected||'Todas as áreas';const m=pointRoute(selected,null);$('selectedStation').textContent=selected==='Administração'?'Incêndio: SADI 4 · Loop 6 (planta 720). Intrusão / CFTV: interface por identificar.':m?`${m.station} · Loop ${m.loop} (referência documental da zona comum; por conferir)`:selected.startsWith('Casa ')?'Central / loop da numeração actual: correspondência por confirmar':'Central / loop: seleccionar uma área';const ev=db.events.filter(e=>(!selected||e.area===selected)&&($('eventFilter').value==='all'||e.status!=='closed')).slice().reverse();$('events').innerHTML=ev.length?ev.map(e=>`<article class="event ${['Avaria','Sem comunicação'].includes(e.type)?'fault':''} ${e.status==='closed'?'closed':''}"><span class="badge">${e.source==='simulation'?'SIMULAÇÃO':'REGISTO MANUAL'}</span> <span class="badge">${({open:'Aberta',ack:'Reconhecida na ficha',closed:'Ficha encerrada'})[e.status]}</span><h3>${esc(e.type)} · ${esc(e.area)}</h3><p>${esc(e.place)} ${e.point?'· '+esc(e.point):''}</p>${e.point?`<p>${esc(e.equipment||'Equipamento identificado pelo código')} · ${esc(e.locationVerified||'Local por confirmar')}</p><p>Posição: ${esc(e.physical||'por levantar')}<br>Endereço: ${esc(e.address||'por levantar')}</p><button data-locate="${esc(e.id)}">Ver localização do equipamento</button>`:''}${e.station?`<p class="muted">${esc(e.station)}${e.loop?' · Loop '+esc(e.loop):''} · referência documental, por conferir</p>`:''}${!e.station&&currentStationMapping[e.area.replace(/^Casa /,'')]?`<p class="muted">${esc(currentStationMapping[e.area.replace(/^Casa /,'')].station)} · Loop ${currentStationMapping[e.area.replace(/^Casa /,'')].loop} · conforme planta, por conferir</p>`:''}<small>${fmt(e.time)} · Luanda</small><p>${esc(e.notes)}</p><div class="toolbar">${e.status!=='closed'?`<button data-action="ack" data-id="${esc(e.id)}" ${e.status==='ack'?'disabled':''}>Reconhecer ficha</button><button data-action="support" data-id="${esc(e.id)}">Registar atendimento</button><button data-action="isolate" data-id="${esc(e.id)}">Pedido de isolamento</button><button data-action="close" data-id="${esc(e.id)}">Encerrar ficha</button>`:''}</div>${e.log.length?'<details><summary>Histórico de atendimento</summary>'+e.log.map(l=>`<p><small>${fmt(l.time)}</small><br>${esc(l.text)}</p>`).join('')+'</details>':''}</article>`).join(''):'<div class="empty">Sem ocorrências registadas neste filtro. O estado da central continua desconhecido.</div>';
$('pointRows').innerHTML=db.points.length?db.points.map(p=>`<tr><td>${esc(p.code)}<br><small>${esc(p.kind)}</small></td><td>${esc(p.area)}<br>${esc(p.place)}</td><td>${esc(p.model||'Modelo por levantar')}<br><small>${esc(p.address||'Endereço por levantar')}</small></td><td>${esc(p.verified||'Por verificar')}</td><td><button data-edit="${esc(p.id)}">Editar</button></td></tr>`).join(''):'<tr><td colspan="5">Nenhum equipamento cadastrado. Crie uma ficha piloto e confira cada ponto em campo.</td></tr>';
$('testHistory').innerHTML=db.tests.slice().reverse().map(t=>`<details><summary>${esc(t.area)} · ${fmt(t.time)} · ${t.checks.filter(Boolean).length}/${checks.length} verificações</summary><p>${esc(t.notes)}</p>${checks.map((c,i)=>`<p>${t.checks[i]?'☑':'☐'} ${esc(c)}</p>`).join('')}</details>`).join('');}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));['monitor','inventory','tests','guide','integration'].forEach(id=>$(id).hidden=id!==b.dataset.tab);});
$('houses').onclick=$('mapPoints').onclick=e=>{const b=e.target.closest('[data-house]');if(b){selected=area(b.dataset.house);selectedEquipment='';render();$('residenceDetail').scrollIntoView({behavior:'smooth',block:'start'});}};document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{selected=b.dataset.area;selectedEquipment='';if(['Administração','Salão de festas','Ginásio','Guarita Social 1','Guarita Social 2','Guarita de Serviço','Segurança geral'].includes(selected)){['monitor','inventory','tests','guide','integration'].forEach(id=>$(id).hidden=id!=='monitor');document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab==='monitor'));}render();if(['Administração','Salão de festas','Ginásio','Guarita Social 1','Guarita Social 2','Guarita de Serviço','Segurança geral'].includes(selected))$('residenceDetail').scrollIntoView({behavior:'smooth',block:'start'});});$('allAreas').onclick=()=>{selected='';render();};$('houseSearch').oninput=render;$('entityFilter').onchange=render;$('eventFilter').onchange=render;
function normalArea(value){const text=value.trim(),inputCode=text.replace(/^casa\s+/i,'').toUpperCase().replace(/\s*\/\s*/g,'/'),code=houseAliases[inputCode]||inputCode;if(['segurança geral','seguranca geral','rondas','cftv geral'].includes(text.toLowerCase()))return 'Segurança geral';const guardName=Object.keys(guardConfig).find(n=>n.toLowerCase()===text.toLowerCase());if(guardName)return guardName;return ['ginásio','ginasio','academia'].includes(text.toLowerCase())?'Ginásio':houseCodes.includes(code)?area(code):['administração','administracao','edifício administrativo','edificio administrativo'].includes(text.toLowerCase())?'Administração':text;}
function residencePoints(a){const code=a.replace(/^Casa /,'');const expected=a==='Segurança geral'?securityEquipment:guardConfig[a]?guardEquipment.filter(p=>p.area===a):a==='Ginásio'?gymEquipment:a==='Administração'?adminEquipment:houseCodes.includes(code)?template.map(([suffix,kind,place])=>({id:'',code:`KZ-ATUAL-${code}-${suffix}`,area:a,kind,place,model:'',address:'',physical:'',verified:'Por verificar',expected:true,source:'BP-GE_AB_SEG_120_T3_00.pdf',system:kind==='Botão de pânico'?'Pânico':'Incêndio',documentLocation:'Símbolo na planta T3 AS BUILT de 05/11/2014; orientação normal/espelhada por confirmar'})):[];return [...expected.map(p=>({...p,...(db.points.find(x=>x.code===p.code&&x.area===a)||{})})),...db.points.filter(p=>p.area===a&&!expected.some(x=>x.code===p.code))];}
function pointRoute(a,p){if(a==='Segurança geral')return {station:'Sistema de segurança / interface por identificar',loop:null};if(guardConfig[a])return !p||p.system==='Incêndio'?{station:guardConfig[a].station,loop:guardConfig[a].loop}:{station:'Central / interface por identificar',loop:null};if(a==='Ginásio'){return !p||p.system==='Incêndio'?{station:'SADI 2',loop:8}:{station:'Central / interface por identificar',loop:null};}if(a==='Salão de festas'){return !p||p.system==='Incêndio'?{station:'SADI 2',loop:7}:{station:'Central / interface por identificar',loop:null};}if(a==='Administração'){return p&&p.system==='Incêndio'?{station:'SADI 4',loop:6}:{station:'Central / interface por identificar',loop:null};}return currentStationMapping[a.replace(/^Casa /,'')]||null;}
function pointStatus(p){return p.verified==='Verificado em campo'&&p.physical&&p.address?'Local verificado em campo':'Local descrito · por confirmar';}
function eventDialog(sim,pointCode=''){simulation=sim;$('eventForm').reset();$('eventForm').elements.area.value=selected;$('eventHeading').textContent=sim?'Simular evento de formação':'Registar ocorrência manual';refreshEventPoints(pointCode);$('eventDialog').showModal();}
function refreshEventPoints(pointCode=''){const f=$('eventForm').elements,a=normalArea(f.area.value);f.area.value=a;f.point.innerHTML='<option value="">Sem ponto individual · área ou circuito</option>'+residencePoints(a).map(p=>`<option value="${esc(p.code)}">${esc(p.kind)} · ${esc(p.place)} · ${esc(p.code)}</option>`).join('');f.point.value=pointCode;fillEventLocation();}
function fillEventLocation(){const f=$('eventForm').elements,p=residencePoints(normalArea(f.area.value)).find(x=>x.code===f.point.value);f.place.readOnly=!!p;if(p){f.place.value=p.place;$('eventLocationHint').textContent=`${pointStatus(p)}. ${p.physical?'Posição: '+p.physical:'Posição física exacta ainda por levantar.'} ${p.address?'Endereço: '+p.address:'Endereço electrónico ainda por levantar.'}`;if(p.kind==='Botão de pânico')f.type.value='Pânico';else if(p.kind==='Sensor de intrusão')f.type.value='Intrusão';else if(p.kind==='Sensor de inundação')f.type.value='Inundação';else if(p.kind.startsWith('Detector ')||p.kind==='Botão de incêndio')f.type.value='Incêndio';else if(p.system==='Incêndio')f.type.value='Incêndio';else if(p.system==='Intrusão')f.type.value='Intrusão';else if(p.system&&['CFTV','Rondas','Rede de segurança','Alarme técnico','Assistência','Protecção portátil'].includes(p.system))f.type.value='Ocorrência técnica';}else{$('eventLocationHint').textContent='Sem ponto individual: descreva a área afectada. Não será destacado um equipamento específico.';}}
$('eventForm').elements.area.onchange=()=>refreshEventPoints();$('eventForm').elements.point.onchange=fillEventLocation;
$('newEvent').onclick=()=>eventDialog(false);$('demoEvent').onclick=()=>eventDialog(true);
$('eventForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),a=normalArea(f.area),p=residencePoints(a).find(x=>x.code===f.point);if(f.point&&!p){toast('O equipamento seleccionado não pertence a esta área. Seleccione-o novamente.');refreshEventPoints();return;}const m=pointRoute(a,p);db.events.push({...f,area:a,place:p?p.place:f.place.trim(),equipment:p?p.kind:'',physical:p?p.physical||'':'',address:p?p.address||'':'',locationVerified:p?pointStatus(p):'Por verificar',system:p?p.system||'':'',station:m?m.station:'',loop:m?m.loop:null,id:uid(),source:simulation?'simulation':'manual',status:'open',time:now(),log:[]});selected=a;selectedEquipment=p?p.code:'';if(a==='Administração'&&p&&p.layer)adminLayer=p.layer;if(a==='Ginásio'&&p&&p.layer)gymLayer=p.layer;if(guardConfig[a]&&p&&p.layer)guardLayer=p.layer;if(a==='Segurança geral'&&p&&p.layer)securityLayer=p.layer;$('eventDialog').close();save();};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
$('events').onclick=e=>{const location=e.target.closest('[data-locate]');if(location){const record=db.events.find(x=>x.id===location.dataset.locate);if(record){selected=record.area;selectedEquipment=record.point;const point=residencePoints(selected).find(p=>p.code===selectedEquipment);if(selected==='Administração'&&point&&point.layer)adminLayer=point.layer;if(selected==='Ginásio'&&point&&point.layer)gymLayer=point.layer;if(guardConfig[selected]&&point&&point.layer)guardLayer=point.layer;if(selected==='Segurança geral'&&point&&point.layer)securityLayer=point.layer;render();$('residenceDetail').scrollIntoView({behavior:'smooth',block:'start'});}return;}const b=e.target.closest('[data-action]');if(!b)return;const v=db.events.find(x=>x.id===b.dataset.id);if(!v)return;action={id:v.id,type:b.dataset.action};$('actionForm').reset();$('isolationFields').hidden=action.type!=='isolate';$('actionForm').elements.deadline.required=action.type==='isolate';const texts={ack:['Reconhecer a ficha','Regista que recebeu esta ocorrência. Não envia reconhecimento à central.'],support:['Registar atendimento','Registe o suporte prestado e o que falta resolver.'],isolate:['Criar pedido de isolamento','Este pedido não desactiva nenhum equipamento. Indique o ponto exacto, motivo, medidas temporárias, responsável e prazo para análise técnica.'],close:['Encerrar ficha','Registe o resultado verificado. Encerrar esta ficha não corrige avarias nem repõe a central.']};$('actionTitle').textContent=texts[action.type][0];$('actionExplanation').textContent=texts[action.type][1]+` Local: ${v.area} · ${v.place}.`;$('actionDialog').showModal();};
$('actionForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),v=db.events.find(x=>x.id===action.id);if(!v)return;if(action.type==='isolate'&&new Date(f.deadline)<=new Date()){toast('Escolha um prazo futuro.');return;}const names={ack:'Reconhecimento da ficha',support:'Atendimento',isolate:'PEDIDO DE ISOLAMENTO — NÃO EXECUTADO',close:'Encerramento da ficha'};v.log.push({time:now(),text:`${names[action.type]} · ${f.operator.trim()} · ${f.reason.trim()}${action.type==='isolate'?' · Prazo '+f.deadline+' (hora local do dispositivo)':''}`});if(action.type==='ack')v.status='ack';if(action.type==='close')v.status='closed';$('actionDialog').close();save();};
function editPoint(p){$('pointForm').reset();Object.keys(p).forEach(k=>{if($('pointForm').elements[k])$('pointForm').elements[k].value=p[k];});$('pointDialog').showModal();}
$('newPoint').onclick=()=>{$('pointForm').reset();$('pointForm').elements.area.value=selected;$('pointDialog').showModal();};$('pointRows').onclick=e=>{const b=e.target.closest('[data-edit]');if(b)editPoint(db.points.find(x=>x.id===b.dataset.edit));};
$('pointForm').onsubmit=e=>{e.preventDefault();let p=Object.fromEntries(new FormData(e.target));const base=residencePoints(normalArea(p.area)).find(x=>x.code===p.code.trim());p={...(base||{}),...p};p.code=p.code.trim();p.area=normalArea(p.area);if(p.verified==='Verificado em campo'&&(!p.physical.trim()||!p.address.trim())){toast('Para confirmar em campo, indique a posição física e o endereço electrónico verificados.');return;}if(db.points.some(x=>x.code===p.code&&x.id!==p.id)){toast('Já existe um equipamento com esse código.');return;}if(p.id){db.points[db.points.findIndex(x=>x.id===p.id)]=p;}else{p.id=uid();db.points.push(p);}$('pointDialog').close();save();};
const template=[["BP-P0-DT-SALA", "Detector termovelocimétrico", "Piso 0 · Sala de estar / jantar"], ["BP-P0-DT-COZ", "Detector termovelocimétrico", "Piso 0 · Cozinha"], ["BP-P0-DF-LAV", "Detector óptico de fumo", "Piso 0 · Lavandaria"], ["BP-P1-DA-S1", "Detector de fumo óptico-acústico", "Piso 1 · Suite 01"], ["BP-P1-DA-S2", "Detector de fumo óptico-acústico", "Piso 1 · Suite 02"], ["BP-P1-DA-MASTER", "Detector de fumo óptico-acústico", "Piso 1 · Suite master"], ["BP-P0-BP-VEST", "Botão de pânico", "Piso 0 · Vestíbulo"], ["BP-P1-BP-MASTER", "Botão de pânico", "Piso 1 · Suite master"], ["BP-P0-SOA-ENT", "Sirene óptico-acústica", "Piso 0 · Entrada / acesso ao lavabo"], ["BP-P1-SIR-HALL", "Sirene de alarme", "Piso 1 · Hall / circulação"], ["BP-P1-FLASH-EXT", "Flash estroboscópico", "Piso 1 · Varanda da suite master"], ["BP-P0-AT", "Módulo de entrada AT", "Piso 0 · Despensa / junto ao vestíbulo"], ["BP-P1-AT", "Módulo de entrada AT", "Piso 1 · Hall / circulação"], ["BP-P1-MC", "Módulo de comando MC", "Piso 1 · Hall / circulação"], ["BP-P1-FONTE", "Fonte de alimentação", "Piso 1 · Hall / circulação"]];
function renderResidence(opened){const points=residencePoints(selected);$('residenceDetail').hidden=!houseCodes.includes(selected.replace(/^Casa /,''));if(['Administração','Salão de festas','Ginásio','Guarita Social 1','Guarita Social 2','Guarita de Serviço','Segurança geral'].includes(selected))$('residenceDetail').hidden=false;if($('residenceDetail').hidden)return;$('residenceTitle').textContent=selected+' · Localização dos equipamentos';const entityInfo=residenceEntities[selected.replace(/^Casa /,'')];$('residenceEntity').textContent=entityInfo?`Entidade: ${entityInfo.entity} · Fonte: ${entityInfo.source}${entityInfo.intrusionInstalled?' · Intrusão instalada e em funcionamento, conforme informação do responsável; integração ainda não validada.':''}`:(houseCodes.includes(selected.replace(/^Casa /,''))?'Entidade não indicada no documento.':'');
$('residenceNote').textContent=selected==='Segurança geral'?'Implantação geral CFTV e rondas conforme desenhos AS BUILT de 31/08/2015. Pontos e comunicações por conferir; não existe recepção de vídeo nem leitura de rondas nesta versão.':guardConfig[selected]?'Equipamentos da guarita identificada na planta 106. Camadas 205 e 703 apresentam as três guaritas. Endereços e posições físicas por verificar.':selected==='Ginásio'?'Referências das plantas 104, 203 e 701 de 2015; por verificar em campo. Incêndio: SADI 2 / Loop 8 conforme planta 720. CFTV: interface por identificar.':selected==='Salão de festas'?'Zona comum partilhada. Seis desenhos documentais de 2015; cadastro individual ainda por conferir. Incêndio: SADI 2, Loop 7 conforme planta 720.':selected==='Administração'?'Posições transcritas dos desenhos AS BUILT de 2015, por verificar em campo. Os marcadores identificam símbolos do desenho, não endereços electrónicos. A camada 702 é referência documental de evacuação, sem comandos.':(selected.includes('/')?'Casa unificada: quantidade, distribuição e endereços dos equipamentos por conferir nas duas partes. O esquema T3 é apenas referência documental. ':'')+'Esquema por divisão, sem escala; 15 referências da planta SADI T3 de 05/11/2014, por verificar em campo. Orientação normal/espelhada e posições físicas por confirmar.';
const rooms=[['Piso 0',['Sala de estar / jantar','Cozinha','Lavandaria','Vestíbulo','Entrada / acesso ao lavabo','Despensa / junto ao vestíbulo']],['Piso 1',['Suite 01','Suite 02','Suite master','Hall / circulação','Varanda da suite master']]];
$('equipmentFloors').innerHTML=rooms.map(([floor,places])=>`<div class="floor"><h3>${floor}</h3><div class="rooms">${places.map(room=>{const pp=points.filter(p=>p.place===`${floor} · ${room}`);return `<div class="room"><h4>${esc(room)}</h4>${pp.map(p=>pointButton(p,opened)).join('')||'<small>Sem equipamento descrito nesta divisão</small>'}</div>`}).join('')}</div></div>`).join('');
const extra=points.filter(p=>!rooms.some(([floor,places])=>places.some(room=>p.place===`${floor} · ${room}`)));$('extraEquipment').innerHTML=extra.length?'<h3>Outros equipamentos cadastrados</h3>'+extra.map(p=>pointButton(p,opened)).join(''):'';
if(selected==='Segurança geral')renderSecurityPlans(points,opened);else if(guardConfig[selected]||['Administração','Ginásio'].includes(selected))renderAdminPlans(points,opened);
else if(selected==='Salão de festas')renderSalonDocuments(points,opened);
else $('equipmentFloors').innerHTML+=`<details class="panel"><summary>Planta SADI T3 · normal e espelhada (2014)</summary><p>Referência documental comum; orientação da casa por confirmar. O desenho indica detectores térmicos na sala/cozinha, óptico na lavandaria e combinados nos quartos; pânico nos dois pisos. Esta planta é a única referência adoptada para o modelo residencial; confirmar a instalação em campo. Os símbolos e cotas não são endereços electrónicos.</p><img style="width:100%" src="${residenceDocumentImage}" alt="Planta de incêndio T3 normal e espelhada"><p>Ligação documental desta casa: ${esc((pointRoute(selected,null)||{}).station||'por identificar')} · Loop ${esc((pointRoute(selected,null)||{}).loop||'por identificar')}. Percurso interno nesta planta; distribuição geral conforme plantas 720 e 113. Sem ligação física implementada.</p></details>`;
const p=points.find(p=>p.code===selectedEquipment);$('equipmentInfo').innerHTML=p?`<h3>${esc(p.kind)}</h3><p><strong>${esc(p.area)} → ${esc(p.place)}</strong></p><p><code>${esc(p.code)}</code></p><p>${esc(pointStatus(p))}</p>${p.source?`<p>Fonte: ${esc(p.source)}<br>${esc(p.documentLocation||'')}<br>Sistema: ${esc(p.system||'por identificar')}</p>`:''}<p>Posição física: ${esc(p.physical||'por levantar no local')}</p><p>Endereço electrónico: ${esc(p.address||'por levantar na central')}</p><p>Modelo: ${esc(p.model||'por identificar')}</p><div class="toolbar"><button data-equipment-action="event" class="primary">Registar ocorrência neste ponto</button><button data-equipment-action="simulate">Simular neste ponto</button><button data-equipment-action="edit">Conferir / editar localização</button></div>`:'<p class="muted">Seleccione um equipamento para consultar a localização, o endereço e as ocorrências desse ponto.</p>';
const unlocated=opened.filter(e=>e.area===selected&&(!e.point||!points.some(p=>p.code===e.point)));$('unlocatedEvents').innerHTML=unlocated.length?`<p class="notice">${unlocated.length} ocorrência(s) sem correspondência com um ponto individual. Consulte os registos; não é possível destacar um equipamento exacto.</p>`:'';}

function renderAdminPlans(points,opened){const layers=guardConfig[selected]?guardLayers:selected==='Ginásio'?gymLayers:adminLayers;let layer=layers.find(l=>l.id===(guardConfig[selected]?guardLayer:selected==='Ginásio'?gymLayer:adminLayer))||layers[0];if(guardConfig[selected]&&layer.id==='106')layer={...layer,image:guardConfig[selected].image};const pp=points.filter(p=>p.layer===layer.id);$('equipmentFloors').innerHTML=`<div class="adminPlans"><div class="toolbar">${layers.map(l=>`<button data-admin-layer="${l.id}" class="${l.id===layer.id?'active':''}">${esc(l.title)}</button>`).join('')}</div><p>Planta ${layer.id} · AS BUILT ${layer.date} · clique nos marcadores numerados ou na lista.</p><div class="adminPlan"><img src="${layer.image}" alt="Planta de ${esc(selected)}: ${esc(layer.title)}">${pp.map((p,i)=>{const active=opened.some(e=>e.area===p.area&&e.point===p.code);return `<button class="adminMarker ${active?'affected':''} ${p.code===selectedEquipment?'chosen':''}" style="left:${p.x}%;top:${p.y}%" data-equipment="${esc(p.code)}" title="${esc(p.kind+' · '+p.place)}" aria-label="${esc(p.kind+' · '+p.place)}">${i+1}</button>`}).join('')}</div>${layer.id==='701'?'<p>Sinalização, iluminação e percursos de evacuação; barreira EI60 indicada. Confirmar o estado actual. Números da legenda não são endereços de alarme; barra antipânico é ferragem de evacuação.</p>':layer.id==='702'?'<p>Saídas, percursos de evacuação, iluminação e sinalização de emergência; paredes EI60 e portas E30C/E60C indicadas. Confirmar etiquetas e estado actual. Os números desta planta são referências da legenda, não endereços de alarme.</p>':''}<div class="adminList">${pp.map((p,i)=>`<div><small>Ponto ${i+1} · ${esc(p.place)}</small>${pointButton(p,opened)}</div>`).join('')}</div></div>`;$('extraEquipment').innerHTML=points.some(p=>!p.layer)?'<h3>Outros equipamentos cadastrados</h3>'+points.filter(p=>!p.layer).map(p=>pointButton(p,opened)).join(''):'';}

function pointButton(p,opened){const events=opened.filter(e=>e.area===p.area&&e.point===p.code);return `<button class="equipment ${events.length?'affected':''} ${p.code===selectedEquipment?'chosen':''}" data-equipment="${esc(p.code)}"><strong>${esc(p.kind)}</strong><small>${esc(p.code)}</small><span>${events.length?events.length+' ocorrência(s) aberta(s)':'Sem registo activo · estado real desconhecido'}</span></button>`;}
$('residenceDetail').onclick=e=>{const doc=e.target.closest('[data-salon-document]');if(doc){salonDocument=doc.dataset.salonDocument;render();return;}const securityButton=e.target.closest('[data-security-layer]');if(securityButton){securityLayer=securityButton.dataset.securityLayer;render();return;}const b=e.target.closest('[data-equipment]');const layer=e.target.closest('[data-admin-layer]');if(layer){if(guardConfig[selected])guardLayer=layer.dataset.adminLayer;else if(selected==='Ginásio')gymLayer=layer.dataset.adminLayer;else adminLayer=layer.dataset.adminLayer;render();return;}if(b){selectedEquipment=b.dataset.equipment;render();return;}const a=e.target.closest('[data-equipment-action]');if(!a)return;const p=residencePoints(selected).find(x=>x.code===selectedEquipment);if(!p)return;if(a.dataset.equipmentAction==='edit')editPoint(p);else eventDialog(a.dataset.equipmentAction==='simulate',p.code);};
$('houseTemplate').onclick=()=>{let n=prompt('Código actual da casa na planta (ex.: A71, B12, C18, D14, E10). Cria fichas por verificar, sem sensores de intrusão.');if(n===null)return;n=n.trim().toUpperCase();if(!houseCodes.includes(n)){toast('Código não encontrado na planta.');return;}let count=0;template.forEach(([suffix,kind,place])=>{const code=`KZ-ATUAL-${n}-${suffix}`;if(!db.points.some(p=>p.code===code)){db.points.push({id:uid(),code,kind,place,area:area(n),model:'',address:'',verified:'Por verificar'});count++;}});save();toast(`${count} fichas adicionadas. Confirme os endereços em campo.`);};
const checks=['Aviso e plano de ensaio coordenados com moradores e segurança','Equipamentos e endereços conferidos em campo','Todos os detectores da área ensaiados pelo técnico','Casa, piso e local confirmados no posto','Sirenes previstas e audibilidade verificadas','Pânico / intrusão / inundação ensaiados onde aplicável','Supervisão e avarias testadas pelo técnico','Modos de teste e isolamentos temporários retirados','Estado final e falhas pendentes documentados'];
$('checklist').innerHTML=checks.map((c,i)=>`<label class="check"><input type="checkbox" data-check="${i}"><span>${esc(c)}</span></label>`).join('');$('saveTest').onclick=()=>{const a=$('testArea').value.trim(),notes=$('testNotes').value.trim();if(!a||!notes){toast('Indique a área e o resultado com responsável.');return;}db.tests.push({id:uid(),area:a,time:now(),notes,checks:[...document.querySelectorAll('[data-check]')].map(x=>x.checked)});save();toast('Ficha de teste guardada.');};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kizomba-registos-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('import').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error();const data=JSON.parse(await file.text());if(!valid(data))throw Error();if(!confirm('Substituir os registos deste navegador pela cópia seleccionada? Exporte primeiro a situação actual.'))return;db=mergeUnifiedHouses(migrateImportedNumbering(data));save();toast('Cópia importada.');}catch{toast('Cópia inválida, incompatível ou superior a 5 MB.');}finally{e.target.value='';}};
const steps=[['1 · Identificar o sistema','Registar referência completa da central, firmware, módulos, detectores, botões e sirenes. A placa técnica fotografada confirma Siemens FC726 na Guarita de Serviço. O utilizador confirma a mesma marca e modelo nas quatro centrais. Conferir firmware e módulos de cada central. Obter a planta e o ficheiro de configuração.'],['2 · Tratar o estado actual','Os indicadores AVARIA e ISOLADOS parecem acesos na fotografia. Verificar o estado actual e a protecção afectada antes de alterar programação. Não apagar mensagens para esconder falhas.'],['3 · Cadastrar todos os pontos','Percorrer os códigos da planta actual e as zonas comuns. Registar casa, piso, divisão, função, central, circuito e endereço. Identificar quais são as 60 casas com intrusão.'],['4 · Definir o que cada evento faz','Validar uma matriz causa–efeito com o técnico: incêndio, pânico, intrusão e inundação são eventos distintos. O alcance das sirenes e a evacuação dependem do projecto.'],['5 · Conferir e ligar — técnico','Validar compatibilidade, cablagem, supervisão, capacidade e alimentação pelo manual exacto. Bornes, tensões e resistências não podem ser deduzidos das fotos.'],['6 · Configurar — técnico','Guardar cópia; usar ferramenta e versão compatíveis; mapear pontos e nomes; aplicar a matriz aprovada; testar uma casa piloto. Os endereços de cada casa precisam de validação individual.'],['7 · Testar todos os locais','Ensaiar detectores com equipamento aprovado, botões e saídas previstas. Conferir identificação no posto, sirenes e avarias. Não usar chama ou cigarro para testar.'],['8 · Ligar a supervisão real','Confirmar interface e licenças; receber identificadores individuais; instalar serviço local, base central, contas e auditoria. Validar leitura antes dos comandos.'],['9 · Entregar e formar','Guardar configuração final, planta actualizada, testes e instruções. Treinar reconhecimento, apoio, reposição e isolamento autorizado. Avarias exigem reparação e teste.']];$('steps').innerHTML=steps.map(([t,b])=>`<details><summary>${esc(t)}</summary><p>${esc(b)}</p></details>`).join('');
function mergeUnifiedHouses(data){for(const r of [...data.events,...data.points,...data.tests,...(data.supersededPoints||[])]){const oldCode=r.area?.replace(/^Casa /,'');if(data.layoutVersion===currentLayoutVersion&&houseAliases[oldCode]){r.previousArea=r.previousArea||r.area;r.area=area(houseAliases[oldCode]);r.unifiedHouseSource='União confirmada pelo utilizador · 08/10/2026';}}data.unifiedHousesVersion='2026-10-08';return data;}
try{const stored=JSON.parse(localStorage.getItem(key));if(valid(stored)){db=stored;if(db.layoutVersion!==currentLayoutVersion){for(const record of [...db.events,...db.points,...db.tests,...(db.supersededPoints||[])]){if(/^Casa [A-E]\d{2}$/.test(record.area)){record.previousArea=record.area;record.area=record.area.replace('Casa ','Casa antiga ');record.numbering='Numeração anterior · correspondência pendente';}}db.layoutVersion=currentLayoutVersion;localStorage.setItem(key,JSON.stringify(db));}for(const r of [...db.events,...db.points,...db.tests])if(r.area==='Guarita Social Sul')r.area='Guarita · identificação pendente';if(db.residenceBasis!=='BP120-2014'){const legacy=/^KZ-[A-E]\d{2}-(P0-DF-(SALA|CORR|COZ)|P1-DF-Q[123]|P0-BP-SALA|P0-SIR-ENT|P1-SIR-(HALL|EXT))$/;const retired=db.points.filter(p=>legacy.test(p.code));db.supersededPoints=[...(db.supersededPoints||[]),...retired];db.points=db.points.filter(p=>!legacy.test(p.code));db.residenceBasis='BP120-2014';localStorage.setItem(key,JSON.stringify(db));}}}catch{}
db=mergeUnifiedHouses(db);try{localStorage.setItem(key,JSON.stringify(db));}catch{}
render();

function renderSalonDocuments(points,opened){const doc=salonDocuments.find(d=>d.id===salonDocument)||salonDocuments[0];$('equipmentFloors').innerHTML=`<div class="adminPlans"><div class="toolbar">${salonDocuments.map(d=>`<button data-salon-document="${d.id}" class="${d.id===doc.id?'active':''}">${esc(d.title)}</button>`).join('')}</div><p>Planta ${doc.id} · referência documental de 2015. Não representa o estado actual nem uma ligação activa à central.</p><img style="width:100%" src="${doc.image}" alt="Salão de festas: ${esc(doc.title)}"><p>Hidrantes, sprinklers, extinção de cozinha e sinalização são protecções distintas. Apenas interfaces eléctricas identificadas e compatíveis poderão produzir eventos na supervisão. Não há comandos de extinção nesta demonstração.</p></div>`;$('extraEquipment').innerHTML=points.length?'<h3>Equipamentos cadastrados nesta zona comum</h3>'+points.map(p=>pointButton(p,opened)).join(''):'<p class="notice">Cadastro individual pendente: adicionar código, piso, divisão, posição física e endereço verificados em Equipamentos. As ocorrências sem ponto individual identificam apenas a área.</p>';}

function renderSecurityPlans(points,opened){const layer=securityLayers.find(l=>l.id===securityLayer)||securityLayers[0];const pp=points.filter(p=>p.layer===layer.id);$('equipmentFloors').innerHTML=`<div class="adminPlans"><div class="toolbar">${securityLayers.map(l=>`<button data-security-layer="${l.id}" class="${l.id===layer.id?'active':''}">${esc(l.title)}</button>`).join('')}</div><p>Planta ${layer.id} · AS BUILT 31/08/2015 · referência documental.</p><div class="adminPlan"><img src="${layer.image}" alt="Segurança geral: ${esc(layer.title)}">${pp.map((p,i)=>`<button class="adminMarker ${opened.some(e=>e.area===p.area&&e.point===p.code)?'affected':''} ${p.code===selectedEquipment?'chosen':''}" style="left:${p.x}%;top:${p.y}%" data-equipment="${esc(p.code)}" title="${esc(p.place)}" aria-label="${esc(p.place)}">${i+1}</button>`).join('')}</div><p>${layer.id==='200'?'Implantação de câmaras exteriores, armários e cabos em instalações de comunicações. Os detalhes mostram alimentação e conversão óptica; não definem protocolo, credenciais ou configuração de rede para este software. Inventário individual de câmaras e armários ainda por transcrever e conferir.':'Pontos CHIP 01 a CHIP 09 e referências Rondas 1 a 6. A plataforma regista ocorrências por ponto; não lê chips, não valida passagem de vigilantes e não infere horários ou sequências operacionais.'}</p><div class="adminList">${pp.map(p=>`<div><small>${esc(p.place)}</small>${pointButton(p,opened)}</div>`).join('')}</div></div>`;$('extraEquipment').innerHTML=points.some(p=>!p.layer)?'<h3>Outros equipamentos cadastrados</h3>'+points.filter(p=>!p.layer).map(p=>pointButton(p,opened)).join(''):'';}

function migrateImportedNumbering(data){if(data.layoutVersion!==currentLayoutVersion){for(const r of [...data.events,...data.points,...data.tests,...(data.supersededPoints||[])])if(/^Casa [A-E]\d{2}$/.test(r.area)){r.previousArea=r.area;r.area=r.area.replace('Casa ','Casa antiga ');r.numbering='Numeração anterior · correspondência pendente';}data.layoutVersion=currentLayoutVersion;}return data;}
